<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Exam Setup</h1><p>Connect exams, classes and assigned subjects.</p></div></header><section class="module-card"><div class="module-card__body"><?php $subjectClasses=[];$subjectNames=[];foreach($subjects as$sub){$subjectNames[(int)$sub['id']]=$sub['name'];$subjectClasses[(int)$sub['id']][]=(int)$sub['class_id'];} asort($subjectNames); ?>
<form method="post" action="<?= url('/admin/exams/setup') ?>" class="exam-center" data-ec-setup><?= csrf_field() ?>
<div class="module-form-grid"><div class="module-field"><label for="ec-setup-exam">Exam</label><select class="module-select" id="ec-setup-exam" name="exam" required><?php foreach($exams as$e):?><option value="<?= $e['id'] ?>"><?= e($e['name']) ?></option><?php endforeach ?></select></div>
<div class="module-field"><label for="ec-setup-total">Total marks (each paper)</label><input class="module-input" id="ec-setup-total" type="number" min="1" step="0.01" name="total_marks" required placeholder="e.g. 100"></div></div>
<fieldset class="ec-classes"><legend>Classes <button class="btn btn--ghost btn--sm" type="button" data-ec-tick="classes">Tick all</button></legend>
<div class="ec-check-grid"><?php foreach($classes as$c):?><label class="ec-check"><input type="checkbox" name="classes[]" value="<?= (int)$c['id'] ?>"><span><?= e($c['name']) ?></span></label><?php endforeach ?></div>
<?php if(!$classes):?><p class="ec-muted"><?= !empty($isTeacher)?'You are not assigned to any class yet.':'No classes yet.' ?></p><?php endif ?></fieldset>
<fieldset class="ec-classes"><legend>Subjects <button class="btn btn--ghost btn--sm" type="button" data-ec-tick="subjects">Tick all</button></legend>
<p class="ec-muted" data-ec-setup-hint>Tick one or more classes to see their subjects.</p>
<div class="ec-check-grid"><?php foreach($subjectNames as$sid=>$name):?><label class="ec-check" data-ec-subject-classes="<?= e(implode(',',array_unique($subjectClasses[$sid]))) ?>" hidden><input type="checkbox" name="subjects[]" value="<?= (int)$sid ?>"><span><?= e($name) ?> <small data-ec-subject-note></small></span></label><?php endforeach ?></div></fieldset>
<p class="ec-muted" data-ec-setup-summary hidden></p>
<button class="btn btn--primary" type="submit">Save Exam Setup</button></form></div></section><section class="module-card"><div class="module-card__body"><table class="data-table"><thead><tr><th>Exam</th><th>Class</th><th>Subject</th><th>Total Marks</th><th>Action</th></tr></thead><tbody><?php foreach($setups as$s):?><tr><td><?= e($s['exam_name']) ?></td><td><?= e($s['class_name']) ?></td><td><?= e($s['subject_name']) ?></td><td><?= e($s['total_marks']) ?></td><td><?php if($s['exam_status']==='locked'):?><span class="status-badge">Locked</span><?php else: $mc=(int)$s['marks_count']; ?><form method="post" action="<?= e(url('/admin/exams/setup/'.(int)$s['id'].'/delete')) ?>" onsubmit="return confirm('<?= e($mc>0?'Remove '.$s['subject_name'].' from '.$s['exam_name'].' ('.$s['class_name'].')? The '.$mc.' mark(s) already entered for it will also be deleted.':'Remove '.$s['subject_name'].' from '.$s['exam_name'].' ('.$s['class_name'].')?') ?>')"><?= csrf_field() ?><button class="btn btn--danger btn--sm" type="submit"><i data-lucide="trash-2"></i> Delete</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section></div></div></main>
